<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\SiteSetting;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\View\View;
class MasterSkillsController extends Controller {public function edit():View{return view('admin.home.master-skills',['settings'=>SiteSetting::firstOrCreate([])]);}public function update(Request $r):RedirectResponse{$data=$r->validate(['skills_image'=>['nullable','image','max:4096'],'skills_title'=>['required','string','max:500'],'skills_description'=>['nullable','string','max:2000'],'skills_button_text'=>['required','string','max:100']]);$s=SiteSetting::firstOrCreate([]);if($r->hasFile('skills_image')){if($s->skills_image)Storage::disk('public')->delete($s->skills_image);$data['skills_image']=$r->file('skills_image')->store('site/skills','public');}else unset($data['skills_image']);$s->update($data);return back()->with('status','Master Skills section updated successfully.');}}
